'use strict'

import resource from '../../resource'
import { DIRECTION_EAST, DIRECTION_WEST, ENEMY_GHINI, ENEMY_GRAVE_GHINI } from '../../constant'
import { STATE_DYING, drawImage } from './common'
import { Walker } from './walker'
import { Flyer } from './flyer'

// The ghost of the graveyard (object $21), measured in the ROM: it walks on the grid like an octorok, at
// random and stopped by the scenery, without shooting, and takes many hits. It only has a left and a right side.
// When it dies, the ghinis of the graves die with it (measured: killed by 9 hits of the wooden sword)
class Ghini extends Walker {
  constructor (type, x, y, direction, random = Math.random) {
    super(type, x, y, direction, random)
    this.facing = direction === DIRECTION_WEST ? DIRECTION_WEST : DIRECTION_EAST
  }

  act (map, link) {
    super.act(map, link)
    if (this.direction === DIRECTION_EAST || this.direction === DIRECTION_WEST) {
      this.facing = this.direction
    }
  }

  drawBody (context) {
    drawImage(context, resource.getSprite(`ghini_${this.facing}_move`), 0, this.x, this.y, this.width, this.height)
  }
}

// The ghinis of the graves (object $22), measured in the ROM: one comes out of a grave each time Link starts
// pushing it, 9 at most. Nothing hurts them (life $F0); they take a heart from Link and fly over everything as
// the peahats do (see flyer.js), resting first; when they choose, they go after the target 41 % of the time and
// land 3 % (measured)
const GRAVE_GHINI = { life: Infinity, contactDamage: 1 }
const GRAVE_GHINI_CHANCES = { chase: 0.41, land: 0.03 }
export const MAX_GRAVE_GHINIS = 9
const GRAVE_SPRITE = 'movable_white_rock'

class GraveGhini extends Flyer {
  // master: the ghini of the screen, it dies with it
  constructor (x, y, master, random = Math.random) {
    super(ENEMY_GRAVE_GHINI, x, y, GRAVE_GHINI, GRAVE_GHINI_CHANCES, random)
    this.master = master
    this.fly()
  }

  get isVulnerable () {
    return false
  }

  hit () {}

  knockBack () {}

  act (map, link) {
    if (this.master && (this.master.isDead || this.master.state === STATE_DYING)) {
      this.setState(STATE_DYING)
      return
    }
    super.act(map, link)
  }

  drawBody (context) {
    drawImage(context, resource.getSprite(`ghini_${this.facing}_move`), 0, this.x, this.y, this.width, this.height)
  }
}

// Link pushing a grave of a graveyard (a screen with a ghini): a ghini of the graves comes out of it each time he
// starts pushing it
export function disturbGrave (map, link, tile) {
  const pushing = tile?.sprite?.name === GRAVE_SPRITE && map.enemies?.some(enemy => enemy.type === ENEMY_GHINI) ? tile : undefined
  if (pushing && pushing !== link.pushedGrave) {
    const ghinis = map.activeEnemies.filter(enemy => enemy instanceof GraveGhini && !enemy.isDead)
    if (ghinis.length < MAX_GRAVE_GHINIS) {
      const master = map.activeEnemies.find(enemy => enemy instanceof Ghini && !enemy.isDead && enemy.state !== STATE_DYING)
      map.activeEnemies.push(new GraveGhini(tile.x, tile.y, master))
    }
  }
  link.pushedGrave = pushing
}

export { Ghini, GraveGhini }
